# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl


@triton.jit
def _frac_kernel(A_ptr, out_ptr, N, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    x = tl.load(A_ptr + offs, mask=mask)
    # trunc toward zero via fp32 int32-cast (int cast rounds toward zero).
    # Upcast first: direct narrow-float->int32 is miscompiled on flagtree.
    # fp32 is exact for all fp16/bf16 magnitudes (<=65504 << 2^31) and for
    # fp32 inputs with |x| < 2^31; subtract in fp32 then cast back to dtype.
    xf = x.to(tl.float32)
    t = xf.to(tl.int32).to(tl.float32)
    y = (xf - t).to(x.dtype)
    tl.store(out_ptr + offs, y, mask=mask)


def frac(A):
    Af = A.contiguous().reshape(-1)
    N = Af.numel()
    out_flat = torch.empty_like(Af)
    if N == 0:
        return out_flat.view(A.shape)
    # Small tensors are launch/occupancy-bound and favor more, smaller
    # programs; medium/large tensors favor a big tile (8192 is the measured
    # peak). Pick BLOCK by numel to serve both regimes.
    BLOCK = 1024 if N < 65536 else 8192
    grid = (triton.cdiv(N, BLOCK),)
    _frac_kernel[grid](Af, out_flat, N, BLOCK=BLOCK)
    return out_flat.view(A.shape)
